program.source:
Algoritmo Bisiesto
  Definir anio Como Entero;
  Leer anio;
  Si anio mod 4 = 0 Entonces
    Escribir "Es bisiesto";
  Sino
    Escribir "No es bisiesto";
  FinSi
FinAlgoritmo

